/**
 * Link version 2, frozen: the scenario shapes the channels carry.
 *
 * Written out as concrete types, copied from the shapes the app resolved when link version 2 was cut. It never
 * references the living types, so a change to a handler cannot move it. Do not edit this file to match a changed
 * handler: a change that breaks it needs a new LINK_VERSION and a new `contract/v<N>/` (see protocol.ts for the
 * rule). `tests/remote/contractV2.test.ts` checks the living types against it.
 */

export type ScenarioIssueV2 = { path: string; message: string };

type EntryConditionV2 = {
    type: 'entry';
    select:
        | { by: 'slot'; index: number }
        | { by: 'memory'; slot: string }
        | { by: 'fastest'; window?: string | number; skipProtected?: boolean }
        | { by: 'turbo' | 'mostVotes' | 'fewestVotes' | 'bestRank' | 'worstRank' | 'boosted'; skipProtected?: boolean };
    field: 'turbo' | 'votes' | 'boosted' | 'speedRatio' | 'rank' | 'votesPerHour' | 'boosting';
    op: '<' | '>' | '>=' | '<=' | '=' | '!=';
    value: boolean | number;
    window?: string | number;
};

type ScenarioNotConditionV2 = {
    type: 'not';
    condition:
        | { type: 'dailyWindow'; from: string; to: string }
        | { type: 'beforeEnd' | 'inPhaseFor' | 'afterStart'; min?: string | number; max?: string | number }
        | { type: 'elapsedPercent'; min?: number; max?: number }
        | {
              type: 'exposure' | 'entries' | 'freeSlots' | 'challengeRank' | 'challengeVotes';
              op: '<' | '>' | '>=' | '<=' | '=' | '!=';
              value: number;
          }
        | { type: 'boostState' | 'turboState'; in: string[] }
        | {
              type: 'balance';
              currency: 'keys' | 'swaps' | 'fills' | 'coins';
              op: '<' | '>' | '>=' | '<=' | '=' | '!=';
              value: number;
          }
        | { type: 'memorySet'; slot: string }
        | EntryConditionV2
        | { type: 'all'; of: ScenarioConditionListV2 }
        | { type: 'any'; of: ScenarioConditionListV2 }
        | ScenarioNotConditionV2;
};

type ScenarioConditionListV2 = (
    | { type: 'dailyWindow'; from: string; to: string }
    | { type: 'beforeEnd' | 'inPhaseFor' | 'afterStart'; min?: string | number; max?: string | number }
    | { type: 'elapsedPercent'; min?: number; max?: number }
    | {
          type: 'exposure' | 'entries' | 'freeSlots' | 'challengeRank' | 'challengeVotes';
          op: '<' | '>' | '>=' | '<=' | '=' | '!=';
          value: number;
      }
    | { type: 'boostState' | 'turboState'; in: string[] }
    | {
          type: 'balance';
          currency: 'keys' | 'swaps' | 'fills' | 'coins';
          op: '<' | '>' | '>=' | '<=' | '=' | '!=';
          value: number;
      }
    | { type: 'memorySet'; slot: string }
    | EntryConditionV2
    | { type: 'all'; of: ScenarioConditionListV2 }
    | { type: 'any'; of: ScenarioConditionListV2 }
    | ScenarioNotConditionV2
)[];

type ScenarioRuleV2 = {
    do: (
        | { type: 'enterPhoto'; photo: 'best' | { memory: string }; remember?: string }
        | {
              type: 'swap';
              entry:
                  | { by: 'slot'; index: number }
                  | { by: 'memory'; slot: string }
                  | { by: 'fastest'; window?: string | number; skipProtected?: boolean }
                  | {
                        by: 'turbo' | 'mostVotes' | 'fewestVotes' | 'bestRank' | 'worstRank' | 'boosted';
                        skipProtected?: boolean;
                    };
              with: 'best' | { memory: string };
              rememberRemoved?: string;
              rememberAdded?: string;
          }
        | {
              type: 'boost';
              entry:
                  | { by: 'slot'; index: number }
                  | { by: 'memory'; slot: string }
                  | { by: 'fastest'; window?: string | number; skipProtected?: boolean }
                  | {
                        by: 'turbo' | 'mostVotes' | 'fewestVotes' | 'bestRank' | 'worstRank' | 'boosted';
                        skipProtected?: boolean;
                    };
          }
        | {
              type: 'turbo';
              entry:
                  | { by: 'slot'; index: number }
                  | { by: 'memory'; slot: string }
                  | { by: 'fastest'; window?: string | number; skipProtected?: boolean }
                  | {
                        by: 'turbo' | 'mostVotes' | 'fewestVotes' | 'bestRank' | 'worstRank' | 'boosted';
                        skipProtected?: boolean;
                    };
          }
        | { type: 'unlockBoost' }
        | { type: 'fillExposure' }
        | { type: 'vote'; toExposure: number }
        | {
              type: 'remember';
              slot: string;
              entry:
                  | { by: 'slot'; index: number }
                  | { by: 'memory'; slot: string }
                  | { by: 'fastest'; window?: string | number; skipProtected?: boolean }
                  | {
                        by: 'turbo' | 'mostVotes' | 'fewestVotes' | 'bestRank' | 'worstRank' | 'boosted';
                        skipProtected?: boolean;
                    };
          }
        | { type: 'forget'; slot: string }
        | { type: 'goto'; phase: string }
        | { type: 'notify'; message: string }
    )[];
    id: string;
    label?: string;
    repeat?: 'always' | 'once' | 'oncePerPhase' | 'oncePerDay';
    if?: ScenarioConditionListV2;
};

type ScenarioPhaseV2 = { settings?: { [key: string]: unknown }; rules?: ScenarioRuleV2[] };

export type ScenarioDocumentV2 = {
    start: string;
    version: 1;
    description?: string;
    name: string;
    limits?: { swaps?: number; keys?: number; fills?: number };
    phases: { [key: string]: ScenarioPhaseV2 };
};

type ScenarioFiredRecordV2 = {
    at: number;
    day?: number;
    phaseEnteredAt?: number;
    unclearHalt?: 'unlockBoost' | 'swap' | 'fillExposure';
    haltOrigin?: 'pending';
};

type ScenarioEpochV2 = { all: number; gen: number };

export type ScenarioStateV2 = {
    scenario: string;
    phase: string;
    phaseEnteredAt: number;
    memory: { [key: string]: string };
    fired: { [key: string]: ScenarioFiredRecordV2 };
    inFlight: null | {
        ruleId: string;
        actionIndex: number;
        unclear?: ('unlockBoost' | 'swap' | 'fillExposure')[];
        unclearAt?: number;
        pending?: 'unlockBoost' | 'swap' | 'fillExposure';
        lost?: ('unlockBoost' | 'swap' | 'fillExposure')[];
    };
    spent: { [key: string]: number };
    history?: { [key: string]: [number, number][] };
    outbox?: { id: string; at: number; message: string }[];
    lastAction?: null | { at: number; ruleId: string; action: string; outcome: string };
    lastError?: null | { at: number; message: string };
    updatedAt?: number;
    gen?: number;
    epoch?: ScenarioEpochV2;
};

export type SimulatedEventV2 = {
    at: number;
    phase: string;
    ruleId: string;
    label: string;
    actions: string[];
    toPhase: null | string;
};
